-- duplex_rules.db rule_placement_mix - the mesh mix of each measured band row, from the row's own source elements.
-- Generated by build/project_rule_placement_mix.py (bim-compiler, prompts/MODELLER_MASTER.md BAND-MIX) - regenerate, do not hand-edit.
-- Source: Duplex_extracted.db. 58 rows. Idempotent: the table is rewritten whole on every load.
CREATE TABLE IF NOT EXISTS rule_placement_mix(disc TEXT, ifc_class TEXT, storey_scope TEXT, geometry_hash TEXT, k INTEGER, n INTEGER, src_guid TEXT, bbox_dx REAL, bbox_dy REAL, bbox_dz REAL, element_name TEXT, provenance TEXT, PRIMARY KEY (disc, ifc_class, storey_scope, geometry_hash));
DELETE FROM rule_placement_mix;
